jsonTools.init:
function init(eli) {
  // Kernel-skew-safe aliases: pass-through if kernel pre-eli.events.
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // Storage size warning — moved from kernel §17.3 (2026-05-12).
  // Fires once on tool init. Emits log event + bus event so any UI
  // listener can surface a "running low on storage" banner. Same
  // semantics as v3 boot — just delayed until eli_settings preload.
  (function _checkStorageUsage() {
    if (!eli.storage || !eli.storage.estimate) return;
    eli.storage.estimate().then(function (e) {
      if (!e || !e.percent) return;
      if (e.percent >= 80) {
        eli.log.event("storage", "high_usage", e);
        try { eli.bus.emit("storage:high_usage", e); } catch (err) {}
      }
    });
  })();
  // ── Helpers ─────────────────────────────────────────────────────────
  function _section(panel, title) {
    var h = document.createElement("div");
    h.className = "_eli3_settings_section_head";
    h.textContent = title;
    panel.appendChild(h);
    var box = document.createElement("div");
    box.className = "_eli3_settings_section_body";
    panel.appendChild(box);
    return box;
  }
  function _row(label, control, hint) {
    var r = document.createElement("div");
    r.className = "_eli3_settings_row";
    var main = document.createElement("div");
    main.className = "_eli3_settings_row_main";
    var l = document.createElement("div");
    l.className = "_eli3_settings_label";
    l.textContent = label;
    main.appendChild(l);
    var c = document.createElement("div");
    c.className = "_eli3_settings_control";
    if (control) c.appendChild(control);
    main.appendChild(c);
    r.appendChild(main);
    if (hint) {
      var h = document.createElement("div");
      h.className = "_eli3_settings_hint";
      h.textContent = hint;
      r.appendChild(h);
    }
    return r;
  }
  function _toggle(checked, onchange, labelText) {
    var wrap = document.createElement("label");
    wrap.className = "_eli3_settings_toggle";
    var cb = document.createElement("input");
    cb.type = "checkbox";
    cb.checked = !!checked;
    cb.onchange = function () { onchange(cb.checked); };
    wrap.appendChild(cb);
    var slider = document.createElement("span");
    slider.className = "_eli3_settings_toggle_slider";
    wrap.appendChild(slider);
    if (labelText) {
      var t = document.createElement("span");
      t.className = "_eli3_settings_toggle_label";
      t.textContent = labelText;
      wrap.appendChild(t);
    }
    return wrap;
  }
  function _readUserSettings() {
    try {
      var raw = eli.compat.lsGet("eli_user_settings");
      return raw ? JSON.parse(raw) : {};
    } catch (e) { return {}; }
  }
  function _writeUserSettings(s) {
    try { eli.compat.lsSet("eli_user_settings", JSON.stringify(s)); }
    catch (e) { /* noop */ }
  }

  // ── Shared section builders (used by Global + Interface) ──────────

  // AI Model selector + inline Edit panel (matches v2 lines 5945-6018).
  // v2 stored the user's custom model list inside `userSettings.modelList`
  // (part of the existing `eli_user_settings` blob), NOT a separate key.
  // Earlier v3 builds wrongly added a new `eli_custom_models` localStorage
  // key + a brief IDB-migration detour — both fixed 2026-05-16. We now use
  // v2's actual storage path: read/write `eli_user_settings.modelList`.
  // Sweep the bad key on first read so installs that picked up the wrong
  // builds don't keep stale data sitting around.
  var BUILTIN_MODELS = [
    "gemini-3.1-flash-lite-preview",
    "gemini-2.5-flash",
    "gemini-2.5-pro",
    "gemini-2.0-flash",
  ];
  var _badKeyMigrated = false;
  function _migrateBadKey() {
    if (_badKeyMigrated) return;
    _badKeyMigrated = true;
    try {
      var raw = eli.compat.lsGet("eli_custom_models");
      if (raw) {
        var arr = JSON.parse(raw);
        if (Array.isArray(arr) && arr.length) {
          var s = _readUserSettings();
          var existing = Array.isArray(s.modelList) ? s.modelList : [];
          arr.forEach(function (m) {
            if (m && existing.indexOf(m) === -1) existing.push(m);
          });
          s.modelList = existing;
          _writeUserSettings(s);
        }
        eli.compat.lsRemove("eli_custom_models");
      }
    } catch (e) {}
    // Also clear the brief IDB attempt if it landed for anyone.
    try {
      if (eli.storage && eli.storage.delete) {
        eli.storage.delete("config", "custom_models").catch(function () {});
      }
    } catch (e) {}
  }
  function _readCustomModels() {
    _migrateBadKey();
    var s = _readUserSettings();
    return Array.isArray(s.modelList) ? s.modelList : [];
  }
  function _writeCustomModels(arr) {
    var s = _readUserSettings();
    s.modelList = Array.isArray(arr) ? arr : [];
    _writeUserSettings(s);
  }
  function _allModels() {
    var custom = _readCustomModels();
    var current = eli.ai.getModel();
    var seen = {};
    var out = [];
    custom.concat(BUILTIN_MODELS).concat([current]).forEach(function (m) {
      if (m && !seen[m]) { seen[m] = true; out.push(m); }
    });
    return out;
  }
  function _inlineRow(controlEl, btnEl) {
    var r = document.createElement("div");
    r.className = "_eli3_settings_inline_row";
    if (controlEl) r.appendChild(controlEl);
    if (btnEl) r.appendChild(btnEl);
    return r;
  }

  function _buildAiModelSection(panel) {
    var box = _section(panel, "🤖 AI Model");
    var modelSel = document.createElement("select");
    modelSel.className = "_eli3_input";
    function _populate() {
      modelSel.innerHTML = "";
      var current = eli.ai.getModel();
      _allModels().forEach(function (m) {
        var o = document.createElement("option");
        o.value = m; o.textContent = m;
        if (m === current) o.selected = true;
        modelSel.appendChild(o);
      });
    }
    _populate();
    modelSel.onchange = function () {
      eli.ai.setModel(modelSel.value);
      showToast("Model: " + modelSel.value, "ok");
    };
    var editToggle = document.createElement("button");
    editToggle.type = "button";
    editToggle.className = "_eli3_settings_link_btn";
    editToggle.textContent = "✏️ Edit";
    box.appendChild(_inlineRow(modelSel, editToggle));

    var editPanel = document.createElement("div");
    editPanel.className = "_eli3_settings_inline_panel";
    editPanel.style.display = "none";
    var editList = document.createElement("div");
    editPanel.appendChild(editList);
    var addInput = document.createElement("input");
    addInput.type = "text";
    addInput.className = "_eli3_input";
    addInput.placeholder = "e.g. gemini-2.5-pro-preview";
    var addBtn = eliButton({
      label: "+ Add",
      onclick: function () {
        var name = (addInput.value || "").trim();
        if (!name) return;
        var custom = _readCustomModels();
        if (custom.indexOf(name) !== -1) { showToast("Already in list.", "warn"); return; }
        custom.push(name);
        _writeCustomModels(custom);
        addInput.value = "";
        _renderEditList();
        _populate();
      },
    });
    editPanel.appendChild(_inlineRow(addInput, addBtn));
    box.appendChild(editPanel);

    function _renderEditList() {
      editList.innerHTML = "";
      var custom = _readCustomModels();
      if (!custom.length) {
        var hint = document.createElement("div");
        hint.className = "_eli3_settings_hint";
        hint.textContent = "Built-ins: " + BUILTIN_MODELS.join(", ");
        editList.appendChild(hint);
        return;
      }
      custom.forEach(function (m, i) {
        var row = document.createElement("div");
        row.className = "_eli3_settings_chip_row";
        var name = document.createElement("span");
        name.textContent = m;
        var delBtn = document.createElement("button");
        delBtn.className = "_eli3_settings_chip_del";
        delBtn.textContent = "✕";
        delBtn.onclick = function () {
          var arr = _readCustomModels();
          arr.splice(i, 1);
          _writeCustomModels(arr);
          _renderEditList();
          _populate();
        };
        row.appendChild(name);
        row.appendChild(delBtn);
        editList.appendChild(row);
      });
    }
    editToggle.onclick = function () {
      var open = editPanel.style.display !== "none";
      editPanel.style.display = open ? "none" : "block";
      editToggle.textContent = open ? "✏️ Edit" : "✕ Done";
      if (!open) _renderEditList();
    };
  }

  // Combined: update-check frequency + manual install share a row.
  function _buildMaintenanceSection(panel) {
    var box = _section(panel, "🔧 Maintenance");
    var installGroup = document.createElement("div");
    installGroup.className = "_eli3_settings_maint_cell";
    var installLbl = document.createElement("div");
    installLbl.className = "_eli3_settings_maint_label";
    installLbl.textContent = "Manual Install";
    installGroup.appendChild(installLbl);
    var installBtn = eliButton({
      label: "📦 Import package…",
      variant: "secondary",
      onclick: eli.events.guard(function () {
        if (eli.settings && eli.settings.importPackage) eli.settings.importPackage();
      }, "maint.import"),
    });
    var installLine = document.createElement("div");
    installLine.className = "_eli3_settings_inline_row";
    installLine.appendChild(installBtn);
    installGroup.appendChild(installLine);
    box.appendChild(installGroup);
  }

  function _buildLanguageSection(panel) {
    var box = _section(panel, "🌐 Language");
    var sel = document.createElement("select");
    sel.className = "_eli3_input";
    var LANGS = [
      ["en", "English"], ["es", "Español"], ["fr", "Français"],
      ["de", "Deutsch"], ["it", "Italiano"], ["pt", "Português"],
      ["zh", "中文"], ["ja", "日本語"], ["ru", "Русский"],
    ];
    var current = eli.compat.lsGet("eli_language") || "en";
    LANGS.forEach(function (pair) {
      var o = document.createElement("option");
      o.value = pair[0]; o.textContent = pair[1];
      if (pair[0] === current) o.selected = true;
      sel.appendChild(o);
    });
    sel.onchange = function () {
      eli.compat.lsSet("eli_language", sel.value);
      showToast("Language: " + sel.value, "ok");
    };
    box.appendChild(sel);
  }

  // ── Card 1: 🌍 Global ───────────────────────────────────────────────
  function _buildGlobalDetail(panel) {
    _buildUserProfileSection(panel);
    _buildCredentialsSection(panel);
    _buildAiModelSection(panel);
    _buildLanguageSection(panel);
    _buildTelemetrySection(panel);
    _buildMaintenanceSection(panel);
    _appendSaveChangesButton(panel);
  }

  // 2026-05-17: premium "Saved" confirmation button. All settings here
  // auto-save on toggle change (every _toggle writes to localStorage
  // immediately), so this is purely a CONFIRMATION affordance — user
  // clicks to see a "Settings saved ✓" toast + the button flashes to
  // confirm. Doesn't gate anything (changes already persisted).
  //
  // Explicit colors so it works identically in light AND dark mode —
  // gold gradient on navy text reads premium in both themes. Per the
  // CLAUDE.md "tools/dialogs use light palette in both themes" rule,
  // settings panels are light-mode-only — but the user reported the
  // expanded-width dropdown reading wrong in dark, so we're being
  // belt-and-suspenders here too.
  function _appendSaveChangesButton(panel) {
    var wrap = document.createElement("div");
    wrap.style.cssText = "margin:24px 0 8px;padding:14px 12px 0;" +
      "border-top:1px solid #e2e8f0;display:flex;justify-content:center";
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "_eli3_settings_save";
    btn.style.cssText = "padding:10px 28px;font:800 11.5px/1 'Inter',sans-serif;" +
      "letter-spacing:1.5px;text-transform:uppercase;cursor:pointer;" +
      "background:linear-gradient(180deg,#fef3c7 0%,#fbbf24 100%);" +
      "border:1px solid #d97706;border-bottom-width:2px;" +
      "color:#1c2541;border-radius:3px;" +
      "box-shadow:inset 0 1px 0 rgba(255,255,255,0.5),0 2px 4px rgba(217,119,6,0.18);" +
      "transition:transform 0.12s ease,box-shadow 0.12s ease";
    btn.innerHTML = '<span class="_eli3_settings_save_label">✓ Saved — Click to Confirm</span>';
    btn.onmouseover = function () {
      btn.style.transform = "translateY(-1px)";
      btn.style.boxShadow = "inset 0 1px 0 rgba(255,255,255,0.6),0 4px 10px rgba(217,119,6,0.28)";
    };
    btn.onmouseout = function () {
      btn.style.transform = "";
      btn.style.boxShadow = "inset 0 1px 0 rgba(255,255,255,0.5),0 2px 4px rgba(217,119,6,0.18)";
    };
    btn.onclick = function () {
      // Visual ack — flash the label to green for a beat, then restore.
      var label = btn.querySelector("._eli3_settings_save_label");
      var origText = label ? label.textContent : null;
      var origBg = btn.style.background;
      btn.style.background = "linear-gradient(180deg,#bbf7d0 0%,#22c55e 100%)";
      btn.style.borderColor = "#15803d";
      btn.style.color = "#052e16";
      if (label) label.textContent = "✓ Confirmed";
      if (typeof showToast === "function") showToast("Settings saved.", "ok");
      setTimeout(function () {
        btn.style.background = origBg;
        btn.style.borderColor = "#d97706";
        btn.style.color = "#1c2541";
        if (label && origText) label.textContent = origText;
      }, 1400);
    };
    wrap.appendChild(btn);
    panel.appendChild(wrap);
  }

  // 📊 Usage Telemetry — single row at the bottom of Global. Default-on.
  // Sends a weekday digest of which tools you launch (counts only) to
  // apndrewn/eli-data. Disclosure lives in the description text; toggle
  // is the only required surface. Status + Force Push live in a collapsed
  // "Details" expander so the day-to-day view stays minimal.
  function _buildTelemetrySection(panel) {
    var wrap = document.createElement("div");
    wrap.className = "_eli3_settings_creds";
    var head = document.createElement("div");
    head.className = "_eli3_settings_creds_head";
    head.innerHTML =
      '<span class="_eli3_settings_creds_caret">▶</span>' +
      '<span class="_eli3_settings_creds_title">📊 Usage Telemetry</span>';
    var body = document.createElement("div");
    body.className = "_eli3_settings_creds_body";
    body.style.display = "none";
    head.onclick = function () {
      var open = body.style.display !== "none";
      body.style.display = open ? "none" : "block";
      head.querySelector("._eli3_settings_creds_caret").textContent = open ? "▶" : "▼";
    };
    wrap.appendChild(head);
    wrap.appendChild(body);
    panel.appendChild(wrap);

    // Toggle row. Default = on (unset === "opted_in" semantically).
    var consent = String(eli.compat.lsGet("_telemetry_consent") || "").trim();
    var initialOn = consent !== "opted_out"; // unset OR "opted_in" → on
    body.appendChild(_row(
      "Share usage with admin",
      _toggle(initialOn, function (on) {
        eli.compat.lsSet("_telemetry_consent", on ? "opted_in" : "opted_out");
        showToast(on ? "Telemetry on" : "Telemetry off", "ok");
      }),
      "Sends a weekday digest of which tools you launch (counts only — no document content, no AI prompts, nothing substantive)."
    ));

    // Status + Force Push — debug-y, lives below the toggle in the
    // same expanded panel. Polled when opened.
    function _fmtAgo(ms) {
      if (!ms) return "never";
      var sec = Math.max(0, Math.floor((Date.now() - ms) / 1000));
      if (sec < 60)    return sec + "s ago";
      if (sec < 3600)  return Math.floor(sec / 60) + "m ago";
      if (sec < 86400) return Math.floor(sec / 3600) + "h ago";
      return Math.floor(sec / 86400) + "d ago";
    }
    var statusEl = document.createElement("div");
    statusEl.style.cssText = "font:500 11.5px/1.5 Inter,sans-serif;color:#64748b;padding:6px 0;margin-top:6px;";
    statusEl.textContent = "Loading…";
    body.appendChild(statusEl);
    function _refreshStatus() {
      var status = null;
      try { status = eli.dispatch("telemetry", "status"); }
      catch (e) { status = null; }
      if (!status || typeof status.then !== "function") {
        statusEl.innerHTML = '<span style="color:#b91c1c">Telemetry tool not installed.</span>';
        return;
      }
      status.then(function (s) {
        if (!s) { statusEl.textContent = "Status unavailable."; return; }
        statusEl.innerHTML =
          'User: <b>' + (s.userKey ? String(s.userKey).replace(/[<>&]/g, "") : "(none)") + '</b> · ' +
          'Days captured: <b>' + (s.dayCount || 0) + '</b> · ' +
          'Last push: <b>' + _fmtAgo(s.lastPushAt) + '</b>';
      });
    }
    head.addEventListener("click", function () {
      if (body.style.display !== "none") _refreshStatus();
    });

    var btnRow = document.createElement("div");
    btnRow.style.cssText = "display:flex;gap:8px;flex-wrap:wrap;margin-top:6px";
    btnRow.appendChild(eliButton({
      label: "🚀 Force Push Now",
      variant: "secondary",
      onclick: function () {
        var p = null;
        try { p = eli.dispatch("telemetry", "push"); }
        catch (e) { p = null; }
        if (!p || typeof p.then !== "function") {
          showToast("Telemetry tool not loaded.", "err");
          return;
        }
        showToast("Pushing…", "info");
        p.then(function (r) {
          // 2026-05-17 v23: rich diagnostic — surface consent + self-test
          // result. The push handler runs a synthetic _recordToolLaunch
          // when rowCount is 0, so we can tell apart "write path broken"
          // from "bus events not firing / consent off."
          if (r && r.ok && r.days > 0 && !r.didSelfTest) {
            showToast("Pushed " + r.days + " day" + (r.days === 1 ? "" : "s") + " for '" + (r.userKey || "?") + "'", "ok");
          } else if (r && r.ok) {
            var otherKeys = (r.otherUserKeys && typeof r.otherUserKeys === "object")
              ? Object.keys(r.otherUserKeys) : [];
            var msg;
            if (r.consent === "opted_out") {
              msg = "Push ran but TELEMETRY IS OPTED OUT — bus subscription was never set up at boot, so no launches were captured. Toggle telemetry on in Settings → Global → Usage Telemetry.";
            } else if (r.didSelfTest && r.selfTestOk === false) {
              msg = "Push ran for '" + (r.userKey || "?") + "' but the IDB write self-test FAILED. Check storage permissions.";
            } else if (r.didSelfTest && r.selfTestOk === true) {
              // 2026-05-17 v24: bootState pinpoints WHY the bus
              // subscription didn't happen.
              var bs = r.bootState || {};
              var bootDiag = bs.subscribed
                ? "Bus subscription IS active (step=" + (bs.step || "?") + "). Bus events may be firing but launches with non-appOpened* names don't count — only stats whose name begins with 'appOpened' are recorded. Check the tool you launched fires eli.stats.record('appOpened<Name>')."
                : "Bus subscription FAILED to initialize (step=" + (bs.step || "?") + (bs.error ? ", error=" + bs.error : "") + "). RELOAD the taskpane.";
              msg = "Pushed 1 day for '" + (r.userKey || "?") + "' (self-test row only). REAL launches aren't being recorded. " + bootDiag;
            } else if (otherKeys.length > 0) {
              msg = "Pushed " + r.days + " day(s) for '" + (r.userKey || "?") + "'. Old user key(s) in IDB: " + otherKeys.join(", ") + " — bundle was updated; RELOAD to use new code.";
            } else if (r.days === 0) {
              msg = "Pushed 0 days for '" + (r.userKey || "?") + "'. No data yet — launch a tool then push again.";
            } else {
              msg = "Pushed " + r.days + " day(s) for '" + (r.userKey || "?") + "'.";
            }
            showToast(msg, (r.consent === "opted_out" || r.selfTestOk === false) ? "err" : "warn");
          } else {
            // 2026-05-18 v25: show actual error message (push.error
            // field) when reason is "push_failed" — typically GitHub
            // auth (no PAT / expired) or network.
            var reasonMsg = (r && r.reason) || "unknown";
            var detail = (r && r.error) ? " — " + r.error : "";
            showToast("Push skipped: " + reasonMsg + detail, (reasonMsg === "push_failed") ? "err" : "warn");
          }
          _refreshStatus();
        }).catch(function (e) {
          showToast("Push failed: " + (e && e.message || "unknown"), "err");
        });
      },
    }));
    body.appendChild(btnRow);
  }

  // 👤 User Profile — name / email / group. Stored in localStorage's
  // `eli_user_settings` JSON blob (same shape v2 used). Edits persist
  // on blur. Collapsed by default (matches Keys & Credentials pattern).
  // The Command Center header (above the cards) reads from
  // `eli.tools.userIdentity()` so it auto-refreshes once the user
  // navigates back to the hub. First-name field also auto-derives from
  // the Name field's first whitespace-split token on save, so Auto
  // Emailer greetings still get a sensible value without a separate
  // input.
  function _buildUserProfileSection(panel) {
    function _read() {
      try { var raw = eli.compat.lsGet("eli_user_settings"); return raw ? JSON.parse(raw) : {}; }
      catch (e) { return {}; }
    }
    function _write(patch) {
      var cur = _read();
      Object.keys(patch).forEach(function (k) { cur[k] = patch[k]; });
      try { eli.compat.lsSet("eli_user_settings", JSON.stringify(cur)); } catch (e) {}
    }
    var settings = _read();
    var wrap = document.createElement("div");
    wrap.className = "_eli3_settings_creds";
    var head = document.createElement("div");
    head.className = "_eli3_settings_creds_head";
    head.innerHTML =
      '<span class="_eli3_settings_creds_caret">▶</span>' +
      '<span class="_eli3_settings_creds_title">👤 User Profile</span>';
    var body = document.createElement("div");
    body.className = "_eli3_settings_creds_body";
    body.style.display = "none";
    head.onclick = function () {
      var open = body.style.display !== "none";
      body.style.display = open ? "none" : "block";
      head.querySelector("._eli3_settings_creds_caret").textContent = open ? "▶" : "▼";
    };
    wrap.appendChild(head);
    wrap.appendChild(body);
    panel.appendChild(wrap);

    function _mkInput(opts) {
      var row = document.createElement("div");
      row.className = "_eli3_settings_row";
      var label = document.createElement("div");
      label.className = "_eli3_settings_label";
      label.textContent = opts.label;
      var inp = document.createElement("input");
      inp.type = opts.type || "text";
      inp.className = "_eli3_input";
      inp.value = opts.value || "";
      inp.placeholder = opts.placeholder || "";
      inp.onblur = function () {
        var v = inp.value.trim();
        var patch = {};
        opts.writeKeys.forEach(function (k) { patch[k] = v; });
        if (opts.derive) Object.keys(opts.derive(v)).forEach(function (k) { patch[k] = opts.derive(v)[k]; });
        _write(patch);
        if (typeof showToast === "function") showToast("✅ " + opts.label + " saved", "ok");
      };
      row.appendChild(label);
      row.appendChild(inp);
      return row;
    }
    body.appendChild(_mkInput({
      label: "Name",
      value: settings.name || settings.userName || settings.displayName || "",
      placeholder: "First Last",
      writeKeys: ["name", "displayName"],
      // Auto-derive first name from the leading whitespace-split token
      // so Auto Emailer + Ask ELI greetings keep working without a
      // separate input.
      derive: function (full) {
        var first = String(full || "").trim().split(/\s+/)[0] || "";
        return { firstName: first, userFirstName: first };
      },
    }));
    body.appendChild(_mkInput({
      label: "Email",
      type: "email",
      value: settings.userEmail || settings.email || "",
      placeholder: "you@company.com",
      writeKeys: ["userEmail", "email"],
    }));
    body.appendChild(_mkInput({
      label: "Group",
      value: settings.userGroup || settings.group || "",
      placeholder: "Team / department",
      writeKeys: ["userGroup", "group"],
    }));
    // 2026-05-23: surface the anonymous install UUID. Read-only — it
    // auto-generates on first boot and is the stable identifier admin
    // tooling joins telemetry on. Useful for support ("paste your UUID
    // so I can look you up in fleet"). Format: <FL><LL>-<8 random>.
    var uidRow = document.createElement("div");
    uidRow.className = "_eli3_settings_row";
    var uidLabel = document.createElement("div");
    uidLabel.className = "_eli3_settings_label";
    uidLabel.textContent = "User ID";
    uidRow.appendChild(uidLabel);
    var uidVal = "";
    try {
      uidVal = (eli.settings && eli.settings.get) ? (eli.settings.get("user_id") || "") : "";
      if (!uidVal) uidVal = String(eli.compat.lsGet("eli_user_id") || "");
    } catch (_e) {}
    var uidBox = document.createElement("div");
    uidBox.style.cssText = "display:flex;gap:6px;align-items:center;flex:1;";
    var uidText = document.createElement("code");
    uidText.style.cssText = "font:11.5px/1.4 Monaco,monospace;color:#0f172a;background:#f1f5f9;padding:6px 10px;border:1px solid #cbd5e1;border-radius:3px;flex:1;user-select:all;";
    uidText.textContent = uidVal || "(not generated yet — open any tool to trigger generation)";
    uidBox.appendChild(uidText);
    if (uidVal) {
      var copyBtn = eliButton({
        label: "📋 Copy",
        variant: "secondary",
        style: "padding:6px 10px;font:600 11px/1 system-ui;",
        onclick: function () {
          try {
            (navigator.clipboard ? navigator.clipboard.writeText(uidVal) : Promise.reject())
              .then(function () { showToast("UUID copied", "ok"); })
              .catch(function () {
                // Fallback for browsers without clipboard API
                var ta = document.createElement("textarea");
                ta.value = uidVal;
                document.body.appendChild(ta);
                ta.select();
                try { document.execCommand("copy"); showToast("UUID copied", "ok"); }
                catch (_) { showToast("Copy failed — select manually", "warn"); }
                document.body.removeChild(ta);
              });
          } catch (_e) {}
        },
      });
      uidBox.appendChild(copyBtn);
    }
    uidRow.appendChild(uidBox);
    body.appendChild(uidRow);

    var hint = document.createElement("div");
    hint.style.cssText = "padding:6px 0 0 0;font:400 11px/1.4 Inter,system-ui,sans-serif;color:#94a3b8;";
    hint.textContent = "Name / Email / Group used for activity attribution, audience filtering, and email greetings. Auto-saves on blur. User ID is an anonymous identifier ELI uses for telemetry — read-only.";
    body.appendChild(hint);
  }

  // 🔐 Keys & Credentials — collapsible. Saved values show as masked
  // (populated state). Admin password gates reveal via eye toggle.
  // FROM v2 lines 5137-5215.
  function _buildCredentialsSection(panel) {
    var wrap = document.createElement("div");
    wrap.className = "_eli3_settings_creds";
    var head = document.createElement("div");
    head.className = "_eli3_settings_creds_head";
    head.innerHTML =
      '<span class="_eli3_settings_creds_caret">▶</span>' +
      '<span class="_eli3_settings_creds_title">🔐 Keys &amp; Credentials</span>' +
      '<span class="_eli3_settings_creds_status" id="_eli3_creds_status"></span>';
    var body = document.createElement("div");
    body.className = "_eli3_settings_creds_body";
    body.style.display = "none";
    head.onclick = function () {
      var open = body.style.display !== "none";
      body.style.display = open ? "none" : "block";
      head.querySelector("._eli3_settings_creds_caret").textContent = open ? "▶" : "▼";
    };
    wrap.appendChild(head);
    wrap.appendChild(body);
    panel.appendChild(wrap);

    var importBtn = eliButton({
      label: "📥 Import credentials bundle",
      onclick: function () { eli.settings.importToken({ title: "Import Credentials" }); },
    });
    importBtn.classList.add("_eli3_settings_cred_import");
    body.appendChild(importBtn);

    // _adminUnlock: shared password gate. Built directly on showEliDialog
    // (the single dialog primitive every other dialog uses) with an inline
    // <input type="password"> so chars are always masked, regardless of
    // kernel version. Returns Promise<bool>. Used by Save gating + eye reveal.
    function _adminUnlock(message) {
      return new Promise(function (resolve) {
        var stored = "";
        try { stored = eli.compat.lsGet("eli_admin_password") || ""; } catch (e) {}
        if (!stored) { resolve(true); return; }
        var inputId = "_eli3_admin_pw_" + Math.random().toString(36).slice(2, 8);
        var errId = inputId + "_err";
        showEliDialog({
          variant: "warning",
          tier: "premium",
          icon: "🔒",
          title: "Admin password required",
          body:
            '<div style="margin-bottom:10px">' + (message || "Enter admin password to continue.") + '</div>' +
            '<input id="' + inputId + '" type="password" class="_eli3_input" />' +
            '<div id="' + errId + '" style="color:#c0392b;font-size:11px;margin-top:6px;display:none"></div>',
          primary: {
            label: "Unlock",
            onclick: function (e, ov) {
              var inp = ov.querySelector("#" + inputId);
              var v = inp ? inp.value : "";
              if (v !== stored) {
                var er = ov.querySelector("#" + errId);
                if (er) { er.textContent = "Wrong password."; er.style.display = "block"; }
                if (inp) inp.value = "";
                return false;
              }
              resolve(true);
            },
          },
          secondary: { label: "Cancel", onclick: function () { resolve(false); } },
          onMount: function (ov) {
            setTimeout(function () {
              var i = ov.querySelector("#" + inputId);
              if (i && i.focus) i.focus();
              if (i) {
                i.addEventListener("keydown", function (e) {
                  if (e.key === "Enter") {
                    var btn = ov.querySelector(".eli-dialog-actions button");
                    if (btn) btn.click();
                  }
                });
              }
            }, 50);
          },
          onClose: function () { resolve(false); },
        });
      });
    }

    function _credRow(opts) {
      // opts: {label, accent, getter, setter, hasValue, isSecret, placeholder, isApi}
      var r = document.createElement("div");
      r.className = "_eli3_settings_cred_row";
      var lbl = document.createElement("div");
      lbl.className = "_eli3_settings_cred_label";
      lbl.style.color = opts.accent;
      lbl.textContent = opts.label;
      r.appendChild(lbl);
      var line = document.createElement("div");
      line.className = "_eli3_settings_cred_line";
      var input = document.createElement("input");
      input.type = opts.isSecret ? "password" : "text";
      input.className = "_eli3_input _eli3_settings_cred_input";
      var saved = !!opts.hasValue();
      if (saved && !opts.isSecret) {
        // Non-secret (e.g. branch): show the actual stored value.
        input.value = opts.getter() || "";
        input.placeholder = opts.placeholder || "";
      } else {
        input.placeholder = saved ? "•••••••••••••••• (set)" : (opts.placeholder || "");
      }
      line.appendChild(input);
      if (opts.isSecret) {
        var eye = document.createElement("button");
        eye.className = "_eli3_settings_cred_eye";
        eye.type = "button";
        eye.title = "Reveal (admin password required)";
        eye.textContent = "👁";
        eye.onclick = eli.events.guard(function () {
          if (input.value && input.type === "text") {
            input.type = "password"; eye.textContent = "👁"; return;
          }
          eli.events.safeAsync(_adminUnlock(), "creds.reveal").then(function (ok) {
            if (!ok) return;
            input.value = opts.getter() || "";
            input.type = "text";
            eye.textContent = "🙈";
          });
        }, "creds.eye");
        line.appendChild(eye);
      }
      var save = eliButton({
        label: "Save",
        onclick: eli.events.guard(function () {
          function _commit() {
            var v = (input.value || "").trim();
            if (!v) { showToast("Empty value.", "warn"); return; }
            opts.setter(v);
            if (opts.isSecret) {
              input.value = "";
              input.type = "password";
              input.placeholder = "•••••••••••••••• (set)";
            } else {
              input.value = v;
            }
            showToast(opts.label + " saved.", "ok");
            _refreshStatus();
          }
          if (opts.isAdminPassword || !opts.isSecret) { _commit(); return; }
          eli.events.safeAsync(_adminUnlock("Enter admin password to change " + opts.label + "."), "creds.save-unlock")
            .then(function (ok) { if (ok) _commit(); });
        }, "creds.save"),
      });
      save.classList.add("_eli3_settings_cred_save");
      line.appendChild(save);
      r.appendChild(line);
      body.appendChild(r);
    }

    function _ls(key) {
      return {
        getter: function () { try { return eli.compat.lsGet(key) || ""; } catch (e) { return ""; } },
        setter: function (v) { try { eli.compat.lsSet(key, v); } catch (e) {} },
        hasValue: function () { try { return !!eli.compat.lsGet(key); } catch (e) { return false; } },
      };
    }

    // 🔑 API key — eli.ai stores an encrypted envelope in localStorage AND
    // keeps a plaintext copy in memory (loadApiKey decrypts on boot).
    // eli.ai.getApiKey() returns the in-memory plaintext; the eye toggle
    // still gates the reveal behind the admin password.
    _credRow({
      label: "🔑 Gemini API Key", accent: "#c62828", isSecret: true,
      placeholder: "Paste Gemini API key",
      getter: function () {
        return (eli.ai && typeof eli.ai.getApiKey === "function") ? eli.ai.getApiKey() : "";
      },
      setter: function (v) {
        if (v.length < 10) { showToast("Invalid key.", "warn"); return; }
        eli.ai.setApiKey(v);
        if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
      },
      hasValue: function () { return !!eli.ai.hasApiKey(); },
    });
    var lib = _ls("eli_lib_cipher");
    _credRow(Object.assign({label:"📦 Library Cipher", accent:"#7c2d12", isSecret:true, placeholder:"Library cipher"}, lib));
    var pat = _ls("eli_user_github_pat");
    _credRow(Object.assign({label:"🔑 GitHub PAT", accent:"#0f766e", isSecret:true, placeholder:"github_pat_..."}, pat));
    var repo = _ls("eli_github_repo");
    _credRow(Object.assign({label:"📂 GitHub Repo", accent:"#0d47a1", isSecret:true, placeholder:"owner/repo"}, repo));
    var branch = _ls("eli_github_branch");
    _credRow(Object.assign({label:"🌿 GitHub Branch", accent:"#15803d", isSecret:false, placeholder:"main"}, branch));
    var pw = _ls("eli_admin_password");
    _credRow(Object.assign({label:"🔒 Admin Password", accent:"#7e22ce", isSecret:true, placeholder:"Admin password", isAdminPassword:true}, pw));

    // 2026-05-17: opt-out for the boot-time CDN check. Default ON (true).
    // Lives under Keys & Credentials per user request — connectivity /
    // CDN concern fits here better than under Interface. Kernel reads the
    // same eli_user_settings.autoCheckTools key on boot to decide whether
    // to fire syncFromManifest. Manual checks via "Check for Updates"
    // below stay unaffected.
    (function _wireAutoCheckToolsToggle() {
      var us = _readUserSettings();
      var initial = (us.autoCheckTools === undefined) ? true : !!us.autoCheckTools;
      var t = _toggle(initial, function (v) {
        var cur = _readUserSettings();
        cur.autoCheckTools = v;
        _writeUserSettings(cur);
      });
      var row = _row(
        "🛰️ Auto-Check for New Tools on Load",
        t,
        "On (default): boot fetches the manifest from CDN and surfaces available downloads. Off: skip the check at boot; use 'Check for Updates' below to pull manually."
      );
      // Visual separator from the credential rows above — these are inputs,
      // this is a toggle, so give it a top border + a hair of margin.
      row.style.cssText = "border-top:1px solid #e2e8f0;margin-top:10px;padding-top:10px";
      body.appendChild(row);
    })();

    function _refreshStatus() {
      var keys = ["eli_lib_cipher","eli_user_github_pat","eli_github_repo","eli_github_branch","eli_admin_password"];
      var setCount = keys.filter(function (k) { try { return !!eli.compat.lsGet(k); } catch (e) { return false; } }).length;
      if (eli.ai.hasApiKey()) setCount++;
      var el = wrap.querySelector("#_eli3_creds_status");
      if (el) el.textContent = setCount + " / 6 set";
    }
    _refreshStatus();
  }

  // ── Card 2: ✨ Interface ────────────────────────────────────────────
  function _buildInterfaceDetail(panel) {
    // Header theme. Indices match v2's headerThemeIndex so existing
    // installs keep their saved choice. 2026-05-16: dropped "Classic
    // White" (index 1) and "Minimalist" (index 8) — kept indices stable
    // so the remaining themes don't shift slots. Users still on a
    // removed index render with no theme class (Default appearance) and
    // can re-pick.
    var themeBox = _section(panel, "Header Theme");
    var THEMES = [
      { i: 0, label: "Default",   cls: "" },
      { i: 2, label: "Executive", cls: "theme-executive" },
      { i: 3, label: "Midnight",  cls: "theme-midnight" },
      { i: 4, label: "Oceanic",   cls: "theme-oceanic" },
      { i: 5, label: "Emerald",   cls: "theme-emerald" },
      { i: 6, label: "Royal",     cls: "theme-royal" },
      { i: 7, label: "Copper",    cls: "theme-copper" },
    ];
    var ALL_THEME_CLASSES = THEMES.map(function (t) { return t.cls; })
      .filter(Boolean)
      .concat(["theme-classic-white", "theme-minimalist"]); // sweep removed
    var settings = _readUserSettings();
    var themeSel = document.createElement("select");
    themeSel.className = "_eli3_input";
    THEMES.forEach(function (t) {
      var o = document.createElement("option");
      o.value = String(t.i); o.textContent = t.label;
      if ((settings.headerThemeIndex || 0) === t.i) o.selected = true;
      themeSel.appendChild(o);
    });
    themeSel.onchange = function () {
      var s = _readUserSettings();
      s.headerThemeIndex = parseInt(themeSel.value, 10) || 0;
      _writeUserSettings(s);
      if (eli.dashboard) eli.dashboard.refresh();
      var header = document.querySelector(".header");
      if (!header) return;
      ALL_THEME_CLASSES.forEach(function (c) { header.classList.remove(c); });
      var match = THEMES.filter(function (t) { return t.i === s.headerThemeIndex; })[0];
      if (match && match.cls) header.classList.add(match.cls);
    };
    themeBox.appendChild(themeSel);

    // Behaviors (FROM v2 lines 5279-5306) — Light Mode + 4 toggles +
    // Debug Mode. Each writes a key on the `eli_user_settings` blob to
    // match v2 storage so v2/v3 don't fight.
    var behaviorBox = _section(panel, "Behaviors");
    function _toggleSetting(key, defaultVal, label, hint) {
      var s = _readUserSettings();
      var initial = (s[key] === undefined) ? defaultVal : !!s[key];
      var t = _toggle(initial, function (v) {
        var cur = _readUserSettings();
        cur[key] = v;
        _writeUserSettings(cur);
      });
      behaviorBox.appendChild(_row(label, t, hint));
    }
    _toggleSetting("lightMode", false, "☀️ Light Mode",
      "Switches the taskpane to a light palette. Affects current session — refresh to apply across all paint paths.");
    // Bind the lightMode toggle's behavior to also flip the body class.
    // (We re-create with side effect since _toggleSetting wraps a generic toggle.)
    behaviorBox.lastChild.querySelector("input").addEventListener("change", function (e) {
      if (e.target.checked) document.body.classList.add("light-mode");
      else document.body.classList.remove("light-mode");
    });
    // AI Speech Bubbles toggle removed 2026-05-16 — feature was never
    // ported from v2 to v3. The setting did nothing.
    _toggleSetting("minimizeFeed", false, "📌 Minimize Session Feed on Start",
      "Start the dashboard with the session feed collapsed.");
    _toggleSetting("autoHideSidebar", false, "📊 Auto-Hide Sidebar (Stats Panel)",
      "Hide the stats sidebar by default; re-show via the toggle in the dashboard.");
    // 2026-05-21: Skeleton resolver (Build Draft) — gates the experimental
    // skeleton-hybrid template system. Off by default. When ON, Build Draft
    // detects &[Variant] / #[Clause] markers in template bodies and
    // resolves them against the bd_clauses store (via the Clause Library
    // tool) before Step 1 runs. Templates without those markers behave
    // exactly as today — the resolver is a no-op for them.
    //
    // 2026-05-21 v2: audience-gated to the same admin emails as the
    // Clause Library tool. Non-admin colleagues don't see this toggle
    // at all — they have no Clause Library tool, no clauses, no way
    // to make the feature do anything useful. Hiding the toggle
    // avoids confusion ("what does this do?") and accidental enables.
    // 2026-05-21: narrowed to a single admin while the skeleton system
    // stabilises. Keep in sync with clause_library and build_draft's
    // ALLOWED / _SKELETON_ALLOWED_EMAILS lists — all three need to
    // match for the workflow to function for a given email.
    var _SKELETON_AUDIENCE = {
      "andrew_nemiroff@colpal.com": 1,
    };
    var _curEmail = "";
    try {
      var _ident = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
      _curEmail = String((_ident && _ident.email) || "").toLowerCase().trim();
    } catch (_e) {}
    if (_SKELETON_AUDIENCE[_curEmail]) {
      _toggleSetting("enableSkeletonResolver", false, "🧬 Enable Skeleton Templates (experimental)",
        "Build Draft resolves &[Variant] / #[Clause] markers against the Clause Library. Off = existing template behavior only. Templates without skeleton markers are unaffected either way.");
    }
    // Live-update for the sidebar toggle so the user sees the effect
    // immediately instead of needing a reload. Refresh re-renders the
    // dashboard chrome which re-reads autoHideSidebar via the kernel's
    // _isSidebarCollapsed (now wired to this same setting key).
    behaviorBox.lastChild.querySelector("input").addEventListener("change", function () {
      try { if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh(); } catch (_e) {}
    });
    _toggleSetting("autoExpandWindow", false, "↔️ Auto-Expand Taskpane on Load",
      "Office.js expands the taskpane width on every reload. Off = honor the user's last-set width.");

    // 2026-05-17: show / hide the floating "Click to Expand ELI" pill.
    // Default ON (true). When off, the kernel removes the pill from the
    // DOM immediately (via the settings:changed bus event the kernel
    // subscribes to) AND on every future boot. Persists via
    // eli_user_settings.showExpandPill.
    _toggleSetting("showExpandPill", true, "🪄 Show 'Click to Expand ELI' chip",
      "Floating gold pill that appears near the session feed when the taskpane is narrow. Off = hide it for this account.");
    // Live-update: fire the kernel's generic settings-changed bus event
    // so _evaluateExpandPill re-checks the new value immediately. Reads
    // the last-appended row's toggle input to wire the onChange.
    (function _wireExpandPillLiveUpdate() {
      var rows = behaviorBox.querySelectorAll("._eli3_settings_row input[type='checkbox']");
      var last = rows.length ? rows[rows.length - 1] : null;
      if (!last) return;
      last.addEventListener("change", function () {
        try { eli.bus.emit("settings:changed", { key: "showExpandPill" }); } catch (_e) {}
      });
    })();

    // 2026-05-17: "Auto-Check for New Tools on Load" moved to the Keys &
    // Credentials section in Global — it's a CDN/connectivity concern,
    // not a visual one. Implementation lives at the end of
    // _buildCredentialsSection.

    // 2026-05-17: expansion-width preset. Controls how wide both paths
    // expand to — boot-time auto-expand AND the "Click to Expand" pill.
    // Default 850 matches the kernel's EXPAND_PILL_WIDTH constant. Saved
    // as eli_user_settings.expandWidth (integer px). Live: re-read by the
    // kernel on every expand call, so a change here takes effect on the
    // NEXT click without needing a reload.
    (function _wireExpandWidthSetting() {
      var EXPAND_PRESETS = [
        { v: 600,  l: "600 px (Compact)" },
        { v: 650,  l: "650 px" },
        { v: 700,  l: "700 px" },
        { v: 750,  l: "750 px" },
        { v: 800,  l: "800 px (Default)" },
        { v: 850,  l: "850 px" },
        { v: 1000, l: "1000 px (Roomy)" },
        { v: 1200, l: "1200 px (Extra Wide)" },
        { v: 1400, l: "1400 px (Maximum)" },
      ];
      var s = _readUserSettings();
      var current = Number(s.expandWidth) || 800;
      var select = document.createElement("select");
      select.className = "_eli3_settings_select";
      // 2026-05-17: explicit hex values (not CSS vars) so the dropdown is
      // readable in dark mode too. Previously used --text-primary which
      // resolved to a light color in dark mode → light text on white bg
      // = invisible. Light bg + slate-900 text + slate-300 border works
      // in both themes (matches CLAUDE.md "tools/dialogs use light
      // palette in both themes" rule).
      select.style.cssText = "padding:5px 9px;font:600 12px/1.2 'Inter',sans-serif;" +
        "border:1px solid #cbd5e1;border-radius:4px;background:#ffffff;" +
        "color:#0f172a;cursor:pointer;min-width:170px;appearance:auto";
      EXPAND_PRESETS.forEach(function (p) {
        var opt = document.createElement("option");
        opt.value = String(p.v);
        opt.textContent = p.l;
        // Force option colors too — some browsers render <option> using
        // OS dark mode (separate from in-page theme), which paints
        // black-on-black when the OS is dark. Explicit colors avoid it.
        opt.style.cssText = "background:#ffffff;color:#0f172a";
        if (p.v === current) opt.selected = true;
        select.appendChild(opt);
      });
      select.addEventListener("change", function () {
        var cur = _readUserSettings();
        cur.expandWidth = Number(select.value) || 800;
        _writeUserSettings(cur);
      });
      behaviorBox.appendChild(_row(
        "📐 Expanded Width (Click to Expand)",
        select,
        "Width Office.js targets when you click the Expand pill (or on boot if Auto-Expand is on)."
      ));
    })();

    // Debug + capture toggles — moved here from the (deferred) Data Hub
    // card. Belong on Interface per v2 layout (v2 line 5304 has the
    // Debug Mode toggle in setGroupView).
    _buildDebugSection(panel);

    // Reset View / Reset All (FROM v2 lines 5307 + 5310-5312).
    var resetBox = _section(panel, "Reset");
    var resetRow = document.createElement("div");
    resetRow.style.cssText = "display:flex;gap:8px;flex-wrap:wrap";
    resetRow.appendChild(eliButton({
      label: "↺ Reset View",
      variant: "secondary",
      onclick: eli.events.guard(function () {
        eli.events.safeAsync(eli.ui.confirm({
          title: "Reset view settings?",
          message: "Resets theme, light mode, sidebar, feed, and behavior toggles. API key and tools are not touched.",
        }), "settings.reset-view").then(function (ok) {
          if (!ok) return;
          var s = _readUserSettings();
          delete s.headerThemeIndex; delete s.lightMode;
          delete s.minimizeFeed;
          delete s.autoHideSidebar; delete s.autoExpandWindow;
          // Sweep legacy aiSpeechBubbles key from existing settings blobs
          // — the toggle was removed 2026-05-16 (never wired in v3).
          delete s.aiSpeechBubbles;
          _writeUserSettings(s);
          document.body.classList.remove("light-mode");
          if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
          showToast("View reset.", "ok");
        });
      }, "reset-view"),
    }));
    resetRow.appendChild(eliButton({
      label: "⚠️ Reset All",
      variant: "danger",
      onclick: eli.events.guard(function () {
        eli.events.safeAsync(eli.ui.confirm({
          title: "Reset everything?",
          message: "Clears local user settings, debug flag, and zoom level. API key, encrypted credentials, and installed tools are NOT touched. Reload after.",
        }), "settings.reset-all").then(function (ok) {
          if (!ok) return;
          try { eli.compat.lsRemove("eli_user_settings"); } catch (e) {}
          try { eli.compat.lsRemove("_eli3_zoom"); } catch (e) {}
          try { eli.compat.lsRemove("eli_rawBlocked"); } catch (e) {}
          try { eli.debug(false); } catch (e) {}
          document.body.classList.remove("light-mode");
          if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
          showToast("All view + debug settings reset.", "ok");
        });
      }, "reset-all"),
    }));
    resetBox.appendChild(resetRow);
    _appendSaveChangesButton(panel);
  }

  // ── Card 3: 🗄️ Data Hub — opens the Data Hub tool (formerly Tool
  // Manager). Single dispatch into the tile handler keeps the Settings
  // card honest — the actual UI lives in the tool bundle.
  function _buildDataHubDetail(panel) {
    var box = document.createElement("div");
    box.className = "_eli3_settings_hint";
    box.style.cssText = "padding:24px 16px;text-align:center;font-size:13px;line-height:1.6";
    box.innerHTML =
      '<div style="font-size:32px;margin-bottom:10px">🗄️</div>' +
      '<b>Manage installed tools and data libraries.</b><br>' +
      '<span style="color:#94a3b8">' +
        'Install, update, force-reinstall, or remove anything ELI has installed locally.' +
      '</span>';
    panel.appendChild(box);
    var btnRow = document.createElement("div");
    btnRow.style.cssText = "text-align:center;margin-top:6px";
    btnRow.appendChild(eliButton({
      label: "🗄️ Open Data Hub",
      onclick: function () {
        try { eli.dispatch("tile", "app_tool_manager"); } catch (e) {}
      },
    }));
    panel.appendChild(btnRow);
  }

  // Split out of the old _buildAdvancedSection — Wrongness Capture +
  // Debug Logging now live on the Interface card (not Data Hub).
  function _buildDebugSection(panel) {
    var capBox = _section(panel, "Wrongness Capture");
    capBox.appendChild(_row(
      "Capture engine runs",
      _toggle(eli.wrongness.isEnabled(), function (v) {
        eli.wrongness.setEnabled(v);
        showToast(v ? "Capture on" : "Capture off", "ok");
      }),
      "Engine inputs/outputs are stored (sanitized — no doc text) so you can replay and report bugs. Capped at " + eli.wrongness.MAX_CAPTURES + " entries."
    ));

    var dbgBox = _section(panel, "Debug Logging");
    dbgBox.appendChild(_row(
      "Verbose console logs",
      _toggle(!!eli.debug(), function (v) {
        eli.debug(v);
        showToast(v ? "Debug on" : "Debug off", "ok");
      }),
      "Off by default. Turn on when reproducing a bug for the developer."
    ));
  }

  // Split out of the old _buildAdvancedSection — Tool Updates + Manifest
  // URL now live on the Global card (admin/connectivity).
  function _buildToolUpdatesSection(panel) {
    var syncBox = _section(panel, "Tool Updates");
    var lastCheckTs = parseFloat(eli.compat.lsGet("eli_lastUpdateCheck")) || 0;
    var lastCheckEl = document.createElement("div");
    lastCheckEl.className = "_eli3_settings_hint";
    lastCheckEl.id = "_eli3_settings_lastcheck";
    function _formatLastCheck(ts) {
      if (!ts) return "Never checked.";
      var d = new Date(ts);
      var sec = Math.floor((Date.now() - ts) / 1000);
      var rel = sec < 60 ? "just now"
        : sec < 3600 ? Math.floor(sec / 60) + "m ago"
        : sec < 86400 ? Math.floor(sec / 3600) + "h ago"
        : Math.floor(sec / 86400) + "d ago";
      return "Last checked: " + d.toLocaleString() + " (" + rel + ")";
    }
    lastCheckEl.textContent = _formatLastCheck(lastCheckTs);
    syncBox.appendChild(lastCheckEl);
    var checkBtn = eliButton({
      label: "🔄 Check for updates now",
      onclick: function () {
        var origLabel = checkBtn.textContent;
        checkBtn.textContent = "⏳ Checking…";
        checkBtn.disabled = true;
        var detailEl = document.getElementById("_eli3_settings_check_detail");
        if (detailEl) detailEl.innerHTML = "";
        // No toasts — inline button text + the detail card below convey
        // result. (User feedback 2026-05-11: too many toasts at once.)
        eli.tools.syncFromManifest({ force: true }).then(function (sync) {
          var inline;
          if (sync.installed && sync.updates && sync.updates.length) {
            inline = "✓ " + sync.installed + " new, " + sync.updates.length + " update" + (sync.updates.length === 1 ? "" : "s");
          } else if (sync.installed) {
            inline = "✓ Installed " + sync.installed;
          } else if (sync.updates && sync.updates.length) {
            inline = "✓ " + sync.updates.length + " update" + (sync.updates.length === 1 ? "" : "s") + " available";
          } else {
            inline = "✓ Up to date";
          }
          checkBtn.textContent = inline;
          setTimeout(function () { checkBtn.textContent = origLabel; checkBtn.disabled = false; }, 2500);
          var lc = document.getElementById("_eli3_settings_lastcheck");
          if (lc) lc.textContent = _formatLastCheck(Date.now());
          _renderCheckDetail(sync);
        }).catch(function (err) {
          checkBtn.textContent = "✗ Check failed";
          setTimeout(function () { checkBtn.textContent = origLabel; checkBtn.disabled = false; }, 2500);
          _renderCheckDetail({ error: err });
        });
      },
    });
    // Tag for the kernel's iPhone-style update badge. eli.dashboard.
    // refreshUpdateBadges walks elements with this attribute and paints
    // the count when pending updates exist.
    checkBtn.setAttribute("data-eli-update-badge", "inline");
    checkBtn.setAttribute("data-eli-badge-id", "_eli3_settings_general_badge");
    var checkWrap = document.createElement("div");
    checkWrap.style.marginTop = "8px";
    checkWrap.appendChild(checkBtn);
    syncBox.appendChild(checkWrap);
    // Trigger badge paint right after mount.
    if (eli.dashboard && typeof eli.dashboard.refreshUpdateBadges === "function") {
      try { eli.dashboard.refreshUpdateBadges(); } catch (e) {}
    }
    var detailWrap = document.createElement("div");
    detailWrap.id = "_eli3_settings_check_detail";
    detailWrap.className = "_eli3_settings_check_detail";
    syncBox.appendChild(detailWrap);
    function _renderCheckDetail(sync) {
      var wrap = document.getElementById("_eli3_settings_check_detail");
      if (!wrap) return;
      if (sync.error) {
        wrap.innerHTML = '<div class="_eli3_settings_check_err">⚠️ ' + String(sync.error.message || sync.error) + '</div>';
        return;
      }
      eli.events.safeAsync(Promise.all([eli.tools.list(), eli.tools.getCachedManifest()]), "settings.check-detail").then(function (r) {
        var installed = r[0] || [];
        var manifest = r[1];
        var installedMap = {};
        installed.forEach(function (t) { installedMap[t.id] = t; });
        var rawBlocked = eli.compat.lsGet("eli_rawBlocked") === "1";
        var customUrl = eli.compat.lsGet("eli_manifest_url");
        var rows = (manifest && manifest.tools || []).map(function (entry) {
          var local = installedMap[entry.id];
          var rTs = entry.lastUpdated || entry.releasedAt || "—";
          var lTs = local ? (local.releasedAt || (local.installedAt ? new Date(local.installedAt).toISOString() : "—")) : "(not installed)";
          var verdict;
          if (!local) {
            verdict = '<span style="color:#1565c0">install</span>';
          } else {
            try {
              var rD = Date.parse(rTs), lD = Date.parse(lTs);
              if (!isNaN(rD) && !isNaN(lD)) {
                verdict = rD > lD
                  ? '<span style="color:#1565c0">↑ update</span>'
                  : rD < lD
                    ? '<span style="color:#94a3b8">local newer</span>'
                    : '<span style="color:#16a34a">in sync</span>';
              } else {
                verdict = '<span style="color:#94a3b8">no timestamps</span>';
              }
            } catch (e) { verdict = '<span style="color:#94a3b8">?</span>'; }
          }
          return '<tr>' +
            '<td>' + (entry.id || "?") + '</td>' +
            '<td title="' + lTs + '">' + (lTs.length > 19 ? lTs.slice(0, 19) : lTs) + '</td>' +
            '<td title="' + rTs + '">' + (String(rTs).length > 19 ? String(rTs).slice(0, 19) : rTs) + '</td>' +
            '<td>' + verdict + '</td>' +
            '</tr>';
        }).join("");
        var srcLabel = customUrl
          ? "custom URL"
          : rawBlocked
            ? "jsdelivr (raw blocked)"
            : "raw.githubusercontent (with jsdelivr fallback)";
        wrap.innerHTML =
          '<div class="_eli3_settings_check_meta">' +
            '<b>Source:</b> ' + srcLabel +
            ' &nbsp;·&nbsp; <b>Tools:</b> ' + (manifest && manifest.tools ? manifest.tools.length : 0) +
          '</div>' +
          '<table class="_eli3_settings_check_table">' +
            '<thead><tr><th>id</th><th>local</th><th>remote</th><th>verdict</th></tr></thead>' +
            '<tbody>' + rows + '</tbody>' +
          '</table>';
      });
    }

    var manifestBox = _section(panel, "Manifest URL");
    // Default URL is token-derived (no hardcoded CDN since 2026-05-12).
    // When a credentials token has been imported, eli_github_repo +
    // eli_github_branch let us reconstruct the same URL the kernel uses
    // for auto-sync. Without a token, "default" is empty — the user
    // either imports a token or pins a URL manually.
    function _deriveDefaultManifestUrl() {
      var repo = eli.compat.lsGet("eli_github_repo");
      var branch = eli.compat.lsGet("eli_github_branch");
      if (!repo || !branch) return "";
      return "https://raw.githubusercontent.com/" + repo + "/" + branch + "/tools-manifest-v3.json";
    }
    var defaultUrl = _deriveDefaultManifestUrl();
    var current = eli.compat.lsGet("eli_manifest_url") || defaultUrl;
    var urlInput = document.createElement("input");
    urlInput.type = "text";
    urlInput.className = "_eli3_input";
    urlInput.value = current;
    urlInput.style.fontFamily = "monospace";
    urlInput.style.fontSize = "11px";
    var urlBtns = document.createElement("div");
    urlBtns.style.cssText = "display:flex;gap:6px;margin-top:8px";
    urlBtns.appendChild(eliButton({
      label: "Save",
      onclick: function () {
        var v = (urlInput.value || "").trim();
        if (!v) v = defaultUrl;
        if (v === defaultUrl) eli.compat.lsRemove("eli_manifest_url");
        else eli.compat.lsSet("eli_manifest_url", v);
        showToast("Manifest URL saved. Restart to apply.", "ok");
      },
    }));
    urlBtns.appendChild(eliButton({
      label: "Reset to default",
      variant: "secondary",
      onclick: function () {
        eli.compat.lsRemove("eli_manifest_url");
        urlInput.value = defaultUrl;
        showToast("Reset to default.", "ok");
      },
    }));
    manifestBox.appendChild(urlInput);
    manifestBox.appendChild(urlBtns);
    var defHint = document.createElement("div");
    defHint.className = "_eli3_settings_hint";
    defHint.style.marginTop = "8px";
    defHint.innerHTML = "Default: <code>" + defaultUrl + "</code>";
    manifestBox.appendChild(defHint);
    manifestBox.appendChild(defHint);
  }

  // Split out of the old _buildAdvancedSection — Manual Install now
  // lives on the Global card (bootstrap-recovery / side-load path).
  function _buildManualInstallSection(panel) {
    var manualBox = _section(panel, "Manual Install");
    var manualHint = document.createElement("div");
    manualHint.className = "_eli3_settings_hint";
    manualHint.innerHTML =
      "Install a tool, data bundle, or credentials token from a local " +
      ".json file. Use this when CDN is unreachable or to side-load a " +
      "pre-release build.";
    manualBox.appendChild(manualHint);
    var manualBtn = eliButton({
      label: "📦 Import package…",
      onclick: function () {
        if (eli.settings && eli.settings.importPackage) eli.settings.importPackage();
      },
    });
    var manualWrap = document.createElement("div");
    manualWrap.style.marginTop = "8px";
    manualWrap.appendChild(manualBtn);
    manualBox.appendChild(manualWrap);
  }

  // ── Card 4: 🪄 Draft Templates ──────────────────────────────────────
  // Hands off to build_draft's `tile_settings` channel, which owns the
  // canonical Templates panel (file-name patterns, per-agreement-type
  // template library, active-doc capture, bulk import/export). The gear
  // icon on the build_draft tile dispatches to the same handler.
  function _buildDraftTemplatesDetail(panel) {
    var handler = window.eli && window.eli.get
      ? window.eli.get("tile_settings", "app_build_draft")
      : null;
    if (typeof handler === "function") {
      // Close Command Center first so the templates panel takes over the
      // dashboard root cleanly (otherwise the two would race for the mount).
      try {
        var overlay = document.getElementById("_eli3_settings_overlay") ||
                      document.querySelector("._eli3_cc_overlay") ||
                      document.querySelector("._eli3_settings_overlay");
        if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
      } catch (e) { /* tolerate */ }
      try { handler(); return; }
      catch (err) {
        var note = document.createElement("div");
        note.style.cssText = "padding:18px;color:#b91c1c;font:600 12px/1.4 'Inter',sans-serif";
        note.textContent = "Templates panel failed: " + (err && err.message || "unknown");
        panel.appendChild(note);
        return;
      }
    }
    // build_draft not installed — surface a clean stub instead of an error.
    var hint = document.createElement("div");
    hint.className = "_eli3_settings_hint";
    hint.style.cssText = "padding:24px 16px;text-align:center;font-size:13px;line-height:1.6";
    hint.innerHTML =
      '<div style="font-size:32px;margin-bottom:10px">🪄</div>' +
      '<b>Build Draft is not installed.</b><br>' +
      '<span style="color:#94a3b8">Install it from the Data Hub to manage draft templates.</span>';
    panel.appendChild(hint);
  }

  // Card: 📊 Telemetry — surface the eli_telemetry tool's consent toggle,
  // last-push timestamp, captured-day count, plus a Force Push button for
  // debugging. Stub gracefully when the tool isn't installed.
  // 2026-05-17: telemetry moved into Global section (no standalone card).
  // The _buildTelemetrySection function lives up in _buildGlobalDetail's
  // chain. Default = opt-in. User can toggle off via Global → Usage Telemetry.

  // Cards with `open` skip the in-Settings detail panel and dispatch
  // straight to a tool. The Data Hub card was previously routed through
  // _buildDataHubDetail (a stub explaining what Data Hub does) — that
  // intermediate panel was friction; now the card opens the tool directly.
  var CARDS = [
    { id: "global",    icon: "🌍", title: "Global",          desc: "API Key, Language, Updates",  build: _buildGlobalDetail },
    { id: "interface", icon: "✨", title: "Interface",       desc: "Themes & Views",              build: _buildInterfaceDetail },
    { id: "datahub",   icon: "🗄️", title: "Data Hub",        desc: "Tools, Prompts, Library",
      open: function () { try { eli.dispatch("tile", "app_tool_manager"); } catch (e) {} } },
    { id: "drafttpl",  icon: "🪄", title: "Draft Templates", desc: "Build Draft Config",          build: _buildDraftTemplatesDetail },
  ];

  // ── Hub renderer ────────────────────────────────────────────────────
  function _renderHub(host) {
    host.innerHTML = "";
    var grid = document.createElement("div");
    grid.className = "_eli3_cc_grid_view";
    var hdr = document.createElement("div");
    hdr.className = "_eli3_cc_header";
    var ident = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
    var identName  = (ident && (ident.name || ident.firstName)) || "(name not set)";
    var identEmail = (ident && ident.email) || "(email not set)";
    var identGroup = (ident && ident.group) || "(group not set)";
    function _h(s) { return String(s == null ? "" : s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
    hdr.innerHTML =
      '<button class="_eli3_cc_back_btn" title="Back to dashboard">←</button>' +
      '<div style="flex:1;min-width:0;">' +
        '<div class="_eli3_cc_title">Command Center</div>' +
        '<div class="_eli3_cc_subtitle">System Preferences</div>' +
        '<div class="_eli3_cc_user_info" style="margin-top:6px;font:600 11px/1.4 Inter,system-ui,sans-serif;color:#cbd5e1;letter-spacing:0.02em;">' +
          '<span style="color:#fef3c7;">' + _h(identName) + '</span>' +
          '<span style="opacity:0.55;margin:0 8px;">·</span>' +
          '<span>' + _h(identEmail) + '</span>' +
          '<span style="opacity:0.55;margin:0 8px;">·</span>' +
          '<span style="text-transform:uppercase;font-size:10px;letter-spacing:0.08em;color:#94a3b8;">' + _h(identGroup) + '</span>' +
        '</div>' +
      '</div>';
    hdr.querySelector("._eli3_cc_back_btn").onclick = function () {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
      else if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
    };
    grid.appendChild(hdr);
    var checkRow = document.createElement("div");
    checkRow.className = "_eli3_cc_check_row";
    var checkBtn = document.createElement("div");
    checkBtn.className = "_eli3_cc_toggle_btn";
    checkBtn.textContent = "🔄 Check for updates";
    // iPhone-style update badge — kernel paints when pending updates exist.
    checkBtn.setAttribute("data-eli-update-badge", "inline");
    checkBtn.setAttribute("data-eli-badge-id", "_eli3_settings_cc_badge");
    checkBtn.onclick = function () { _runCheckForUpdates(checkBtn); };
    checkRow.appendChild(checkBtn);
    grid.appendChild(checkRow);
    // Paint the badge after the command center mounts.
    if (eli.dashboard && typeof eli.dashboard.refreshUpdateBadges === "function") {
      try { eli.dashboard.refreshUpdateBadges(); } catch (e) {}
    }
    var cardGrid = document.createElement("div");
    cardGrid.className = "_eli3_cc_card_grid";
    CARDS.forEach(function (card) {
      var el = document.createElement("div");
      el.className = "_eli3_cc_card";
      el.innerHTML =
        '<span class="_eli3_cc_icon">' + card.icon + '</span>' +
        '<div class="_eli3_cc_card_title">' + card.title + '</div>' +
        '<div class="_eli3_cc_desc">' + card.desc + '</div>';
      el.onclick = function () {
        if (typeof card.open === "function") { card.open(); return; }
        _renderDetail(host, card);
      };
      cardGrid.appendChild(el);
    });
    grid.appendChild(cardGrid);
    var footer = document.createElement("div");
    footer.className = "_eli3_cc_footer_row";
    var lightBtn = document.createElement("div");
    lightBtn.className = "_eli3_cc_toggle_btn";
    var settings = _readUserSettings();
    lightBtn.textContent = settings.lightMode ? "🌙 Switch to Dark" : "☀️ Switch to Light";
    lightBtn.onclick = function () {
      var s = _readUserSettings();
      s.lightMode = !s.lightMode;
      _writeUserSettings(s);
      if (s.lightMode) document.body.classList.add("light-mode");
      else document.body.classList.remove("light-mode");
      lightBtn.textContent = s.lightMode ? "🌙 Switch to Dark" : "☀️ Switch to Light";
    };
    var resetBtn = document.createElement("div");
    resetBtn.className = "_eli3_cc_toggle_btn _eli3_cc_reset_btn";
    resetBtn.textContent = "↺ Reset to Default";
    resetBtn.onclick = eli.events.guard(function () {
      eli.events.safeAsync(eli.ui.confirm({
        title: "Reset to default?",
        message: "Resets theme, light mode, and zoom. API key and tools are not touched.",
      }), "hub.reset").then(function (ok) {
        if (!ok) return;
        var s = _readUserSettings();
        s.headerThemeIndex = 0;
        s.lightMode = false;
        _writeUserSettings(s);
        document.body.classList.remove("light-mode");
        try { eli.compat.lsRemove("_eli3_zoom"); } catch (e) {}
        try { eli.compat.lsRemove("eli_rawBlocked"); } catch (e) {}
        if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
        showToast("Reset to defaults", "ok");
      });
    }, "hub.reset");
    footer.appendChild(lightBtn);
    footer.appendChild(resetBtn);
    grid.appendChild(footer);
    host.appendChild(grid);
  }

  function _renderDetail(host, card) {
    host.innerHTML = "";
    var view = document.createElement("div");
    view.className = "_eli3_cc_detail_view";
    var bar = document.createElement("div");
    bar.className = "_eli3_cc_detail_bar";
    bar.innerHTML =
      '<button class="_eli3_cc_back_btn">←</button>' +
      '<div class="_eli3_cc_detail_title">' + card.icon + ' ' + card.title + '</div>';
    bar.querySelector("._eli3_cc_back_btn").onclick = function () { _renderHub(host); };
    view.appendChild(bar);
    var content = document.createElement("div");
    content.className = "_eli3_cc_detail_body";
    var card2 = document.createElement("div");
    card2.className = "_eli3_cc_detail_card";
    content.appendChild(card2);
    view.appendChild(content);
    host.appendChild(view);
    try { card.build(card2); }
    catch (e) {
      card2.innerHTML = '<div class="_eli3_settings_check_err">Detail render failed: ' + (e.message || e) + '</div>';
    }
  }

  function _runCheckForUpdates(btn) {
    var origLabel = btn.textContent;
    btn.textContent = "⏳ Checking…";
    btn.style.pointerEvents = "none";
    eli.tools.syncFromManifest({ force: true }).then(function (sync) {
      // Restore the button immediately, then open the v2-style downloads
      // dialog (shows "<email> · Downloads" with per-row checkboxes).
      // Replaces the old footer-button pattern — instant, no hunt.
      btn.textContent = origLabel;
      btn.style.pointerEvents = "";
      if (eli.dashboard && eli.dashboard.showDownloadsDialog) {
        eli.dashboard.showDownloadsDialog(sync);
      }
      // Pre-Phase-10c kernels (no showDownloadsDialog) get no fallback
      // toast — user feedback 2026-05-11. The button label revert is
      // sufficient acknowledgement; the dialog is the canonical surface.
    }).catch(function (/* err */) {
      btn.textContent = origLabel;
      btn.style.pointerEvents = "";
      // No toast on failure — inline label revert is the signal.
    });
  }

  // ── show() — public entry point ─────────────────────────────────────
  // Full-area takeover (matches v2's resizable cc-premium-modal + the v3
  // docuscrub pattern). Mount on #_eli3_dashboard_root so the Command
  // Center fills the taskpane and inherits Office.js's natural sizing
  // (vs a fixed-width dialog). On close, eli.dashboard.goHome() rebuilds
  // the dashboard from scratch.
  function show() {
    // Wipe any v2-tool content currently in #output (siblings of the
    // dashboard root) so Settings doesn't render on top of the previous
    // tool's surface. `_eliClaimOutput` preserves the dashboard root
    // (hidden); we then un-hide it and mount into it.
    if (window.eli && window.eli.ui && window.eli.ui.claimOutput) window.eli.ui.claimOutput();
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      // Defensive only — _eliClaimOutput should have created one.
      var out = document.getElementById("output");
      if (out) {
        mount = document.createElement("div");
        mount.id = "_eli3_dashboard_root";
        out.appendChild(mount);
      }
      if (!mount) {
        if (typeof showToast === "function") {
          showToast("Settings can't open — output container missing. Reload the taskpane.", "err");
        }
        return;
      }
    }
    mount.style.display = "";
    // Take over the dashboard area entirely — sidebar + main + footer.
    // The previous dashboard markup is rebuilt on goHome() below.
    mount.innerHTML = "";

    var root = document.createElement("div");
    root.className = "_eli3_cc_root";
    var body = document.createElement("div");
    body.id = "_eli3_cc_body";
    body.className = "_eli3_cc_body_full";
    root.appendChild(body);
    mount.appendChild(root);
    _renderHub(body);
  }

  // Override the kernel's stub. importToken / importPackage / maybeFirstRun
  // stay kernel-side (onboarding + manual install per CLAUDE.md).
  eli.settings.show = show;
  eli.log.event("tool", "eli_settings_initialized", {});
}

jsonTools.css:
/* eli_settings tool styles. Injected by kernel as <style data-tool="eli_settings">. */

/* ─── Command Center skeleton ─────────────────────────────────────── */
._eli3_cc_root {
  display: flex; flex-direction: column; width: 100%; height: 100%;
  min-height: 100%; box-sizing: border-box;
  background: #fff; overflow: hidden;
}
._eli3_cc_body_full { flex: 1 1 auto; overflow-y: auto; width: 100%; }
._eli3_cc_grid_view { padding: 14px 16px 18px; background: #fff; }

._eli3_cc_header {
  display: flex; align-items: center; gap: 10px; margin-bottom: 12px;
  padding-bottom: 10px; border-bottom: 1px solid #e2e8f0;
}
._eli3_cc_back_btn {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #64748b;
  padding: 0 4px; line-height: 1;
}
._eli3_cc_back_btn:hover { color: #1565c0; }
._eli3_cc_title { font: 800 17px/1.2 'Georgia', serif; color: #0f172a; letter-spacing: -0.2px; }
._eli3_cc_subtitle {
  font: 700 9px/1 'Inter', sans-serif; color: #64748b;
  text-transform: uppercase; letter-spacing: 1.2px; margin-top: 3px;
}

._eli3_cc_check_row { text-align: center; margin-bottom: 12px; }
._eli3_cc_toggle_btn {
  display: inline-block; padding: 8px 18px;
  font: 800 11px/1.2 'Inter', sans-serif;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff; border: 1px solid rgba(0,0,0,0.1);
  cursor: pointer; text-transform: uppercase; letter-spacing: 0.5px;
  transition: transform .12s, box-shadow .12s; user-select: none;
}
._eli3_cc_toggle_btn:hover { transform: translateY(-1px); box-shadow: 0 4px 10px rgba(21,101,192,0.3); }

._eli3_cc_card_grid {
  display: grid; grid-template-columns: repeat(2, 1fr);
  gap: 8px; margin-bottom: 14px;
}
._eli3_cc_card {
  background: #fff; border: 1px solid #cbd5e1;
  padding: 14px 10px; display: flex; flex-direction: column;
  align-items: center; text-align: center; cursor: pointer;
  transition: transform .15s, box-shadow .15s, border-color .15s;
  box-shadow: 0 2px 6px rgba(0,0,0,0.03), inset 0 1px 0 rgba(255,255,255,0.6);
}
._eli3_cc_card:hover {
  transform: translateY(-2px); border-color: #3b82f6;
  box-shadow: 0 8px 18px rgba(59,130,246,0.13);
}
._eli3_cc_icon { font-size: 26px; margin-bottom: 4px; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.06)); }
body.light-mode ._eli3_cc_icon { filter: none; }
@media (max-width: 380px) {
  ._eli3_cc_card_grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 320px) {
  ._eli3_cc_icon { display: none; }
}
._eli3_cc_card_title { font: 800 13px/1.2 'Inter', sans-serif; color: #0f172a; }
._eli3_cc_desc {
  font: 600 10px/1.2 'Inter', sans-serif; color: #64748b;
  text-transform: uppercase; letter-spacing: 0.4px; margin-top: 2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%;
}

._eli3_cc_footer_row {
  display: flex; justify-content: space-between; gap: 8px;
  border-top: 1px dashed rgba(100,116,139,0.3); padding-top: 12px;
}
._eli3_cc_footer_row ._eli3_cc_toggle_btn {
  flex: 1; display: flex; align-items: center; justify-content: center;
  gap: 6px; text-align: center;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  border: 1px solid #b0bec5; border-top: 1px solid #cfd8dc;
  box-shadow: inset 0 1px 0 #ffffff, 0 1px 2px rgba(0,0,0,0.08);
  color: #546e7a; font-weight: 700; text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}
._eli3_cc_footer_row ._eli3_cc_toggle_btn:hover {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  border-color: #90caf9; color: #1565c0;
  transform: translateY(-1px);
  box-shadow: inset 0 1px 0 #fff, 0 4px 8px rgba(21,101,192,0.15);
}
._eli3_cc_reset_btn { color: #ef4444 !important; }
._eli3_cc_reset_btn:hover {
  background: linear-gradient(to bottom, #fff5f5 0%, #fee2e2 100%) !important;
  border-color: #ef4444 !important; color: #b91c1c !important;
}

/* ─── Detail view ─────────────────────────────────────────────────── */
._eli3_cc_detail_view { display: flex; flex-direction: column; background: #fff; height: 100%; min-height: 100%; }
._eli3_cc_detail_bar {
  display: flex; align-items: center; padding: 10px 14px;
  border-bottom: 1px solid #e2e8f0; background: #fff; flex-shrink: 0;
}
._eli3_cc_back_btn { background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #64748b; padding: 0 8px 0 0; }
._eli3_cc_back_btn:hover { color: #1565c0; }
._eli3_cc_detail_title { flex: 1; font: 800 14px/1.2 'Inter', sans-serif; color: #0f172a; text-align: center; margin-right: 30px; }
._eli3_cc_detail_body { flex: 1; overflow-y: auto; padding: 18px 0 24px; }
._eli3_cc_detail_card {
  max-width: 75%;
  margin: 0 auto;
  padding: 14px;
  border: 1px solid #cbd5e1;
  background: #fff;
}

/* ─── Section pattern — eyebrow + body, all centered. ────────────── */
._eli3_settings_section_head {
  font: 800 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  color: #0f172a; margin: 12px 0 4px;
  padding-bottom: 4px; border-bottom: 1px solid #e2e8f0;
  text-align: center;
}
._eli3_settings_section_head:first-child { margin-top: 0; }
._eli3_settings_section_body { padding: 4px 0 6px; text-align: center; }

/* Settings row: label left, control right, hint full-width below. */
._eli3_settings_row {
  display: block;
  padding: 6px 0 8px;
  border-bottom: 1px solid #f1f5f9;
}
._eli3_settings_row:last-child { border-bottom: none; }
._eli3_settings_row_main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
._eli3_settings_label {
  font: 600 12px/1.3 'Inter', sans-serif;
  color: #1e293b;
  flex: 1; text-align: left;
}
._eli3_settings_control {
  display: flex; align-items: center; gap: 6px;
  flex: 0 0 auto;
}
._eli3_settings_hint {
  font: 400 11px/1.35 'Inter', sans-serif;
  color: #64748b;
  margin: 4px 0 0;
  text-align: left;
}

/* ─── Inline (input + suffix + button on same line, centered) ─────── */
._eli3_settings_inline_row {
  display: flex; gap: 6px; align-items: center; justify-content: center;
  margin-top: 4px;
}

/* Maintenance row: two cells side-by-side (Update-Check | Manual Install). */
._eli3_settings_maint_row {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  justify-content: center;
}
._eli3_settings_maint_cell {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
._eli3_settings_maint_label {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #475569;
  text-align: center;
}
._eli3_settings_inline_row > ._eli3_input { flex: 1; }
._eli3_input._eli3_settings_input_short { width: 64px !important; flex: 0 0 auto !important; text-align: center; }
._eli3_settings_inline_suffix { font: 600 11px/1.4 'Inter', sans-serif; color: #475569; }
._eli3_settings_link_btn {
  background: none; border: none; cursor: pointer;
  font: 700 11px/1 'Inter', sans-serif; color: #1565c0;
  padding: 4px 6px; flex: 0 0 auto;
}
._eli3_settings_link_btn:hover { text-decoration: underline; }
._eli3_settings_inline_panel {
  margin-top: 6px; padding: 8px 10px;
  background: #f8fafc; border: 1px solid #e2e8f0;
}
._eli3_settings_chip_row {
  display: flex; align-items: center; gap: 8px;
  padding: 4px 0; font: 600 11px/1.3 'JetBrains Mono', monospace;
  color: #0f172a;
}
._eli3_settings_chip_row > span:first-child { flex: 1; }
._eli3_settings_chip_del {
  background: none; border: none; cursor: pointer;
  color: #ef4444; font: 800 12px/1 'Inter', sans-serif;
}

/* ─── Inputs ──────────────────────────────────────────────────────── */
._eli3_input {
  width: 100%; padding: 6px 8px;
  border: 1px solid #cbd5e1; background: #fff;
  font: 12px 'Inter', sans-serif; color: #0f172a;
  box-sizing: border-box;
}
._eli3_input:focus { outline: none; border-color: #1565c0; }

/* ─── Toggle switch ───────────────────────────────────────────────── */
._eli3_settings_toggle { display: inline-flex; align-items: center; gap: 6px; cursor: pointer; user-select: none; }
._eli3_settings_toggle input[type="checkbox"] { position: absolute; opacity: 0; pointer-events: none; }
._eli3_settings_toggle_slider {
  width: 32px; height: 16px; background: #cbd5e1;
  position: relative; transition: background 0.15s; display: inline-block;
}
._eli3_settings_toggle_slider::after {
  content: ""; position: absolute; top: 2px; left: 2px;
  width: 12px; height: 12px; background: #fff; transition: left 0.15s;
}
._eli3_settings_toggle input:checked + ._eli3_settings_toggle_slider { background: #1565c0; }
._eli3_settings_toggle input:checked + ._eli3_settings_toggle_slider::after { left: 18px; }
._eli3_settings_toggle_label { font: 600 12px/1.3 'Inter', sans-serif; color: #1e293b; }

/* ─── Keys & Credentials ──────────────────────────────────────────── */
._eli3_settings_creds { border: 1px solid #cbd5e1; background: #fff; margin: 0 0 12px; }
._eli3_settings_creds_head {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  padding: 9px 12px; cursor: pointer; user-select: none;
  background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%);
  border-bottom: 1px solid transparent;
}
._eli3_settings_creds_head ._eli3_settings_creds_title { flex: 0 1 auto; }
._eli3_settings_creds_head ._eli3_settings_creds_status { margin-left: 4px; }
._eli3_settings_creds_caret { font: 700 9px/1 'Inter', sans-serif; color: #475569; width: 10px; }
._eli3_settings_creds_title {
  font: 800 11px/1 'Inter', sans-serif; text-transform: uppercase;
  letter-spacing: 0.5px; color: #0f172a; flex: 1;
}
._eli3_settings_creds_status {
  font: 700 10px/1 'Inter', sans-serif; color: #64748b;
  background: #e2e8f0; padding: 3px 8px;
}
._eli3_settings_creds_body { padding: 8px 10px; border-top: 1px solid #e2e8f0; }
._eli3_settings_cred_import { width: 100%; margin-bottom: 8px; }
._eli3_settings_cred_row { padding-bottom: 6px; margin-bottom: 6px; border-bottom: 1px dashed #e2e8f0; }
._eli3_settings_cred_row:last-child { border-bottom: none; margin-bottom: 0; padding-bottom: 0; }
._eli3_settings_cred_label {
  font: 700 10px/1.2 'Inter', sans-serif; text-transform: uppercase;
  letter-spacing: 0.4px; margin-bottom: 3px; text-align: center;
}
._eli3_settings_cred_line { display: flex; gap: 4px; align-items: center; justify-content: center; }
._eli3_settings_cred_input { flex: 1; font: 11px 'JetBrains Mono', monospace; padding: 5px 8px; }
._eli3_settings_cred_eye {
  background: #f8fafc; border: 1px solid #cbd5e1; cursor: pointer;
  padding: 4px 8px; font-size: 14px; line-height: 1;
  color: #475569;
}
._eli3_settings_cred_eye:hover { background: #e2e8f0; color: #0f172a; }
._eli3_settings_cred_save { padding: 5px 10px !important; font-size: 11px !important; }

/* ─── Dark mode ───────────────────────────────────────────────────── */
body.beta-ui-active:not(.light-mode) ._eli3_cc_root,
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_grid_view,
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_detail_view,
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_detail_bar {
  background: linear-gradient(160deg, #0f172a 0%, #1e293b 100%);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_header { border-bottom-color: rgba(255,255,255,0.12); }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_title { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_subtitle { color: #94a3b8; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_back_btn { color: #cbd5e1; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_back_btn:hover { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_card {
  background: rgba(255,255,255,0.04); border-color: rgba(255,255,255,0.10);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_card:hover { border-color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_card_title { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_desc { color: #94a3b8; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_detail_title { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_detail_bar { border-bottom-color: rgba(255,255,255,0.10); }

body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_section_head {
  color: #f2d866;
  border-bottom-color: rgba(255,255,255,0.12);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_detail_card {
  background: rgba(255,255,255,0.03);
  border-color: rgba(255,255,255,0.12);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_label,
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_toggle_label {
  color: #e2e8f0;
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_hint,
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_inline_suffix {
  color: #94a3b8;
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_row {
  border-bottom-color: rgba(255,255,255,0.06);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_input,
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_cred_input {
  background: rgba(255,255,255,0.06); border-color: rgba(255,255,255,0.15); color: #e2e8f0;
  /* Tells the browser's native form controls (select dropdown options
     in particular) to render with a dark color scheme — otherwise the
     open <option> list paints white-background + our white-ish text
     which is invisible. */
  color-scheme: dark;
}
/* Explicit option background+color — belt-and-suspenders alongside
   color-scheme since some browsers still ignore that for legacy
   native dropdowns. */
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_input option {
  background: #1c2541;
  color: #e2e8f0;
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_input::placeholder,
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_cred_input::placeholder {
  color: rgba(226,232,240,0.4);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_input:focus { border-color: #f2d866; background: rgba(255,255,255,0.10); }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_toggle_slider { background: rgba(255,255,255,0.18); }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_toggle_slider::after { background: #e2e8f0; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_toggle input:checked + ._eli3_settings_toggle_slider { background: #f2d866; }

body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_creds {
  background: rgba(255,255,255,0.04); border-color: rgba(255,255,255,0.12);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_creds_head {
  background: rgba(255,255,255,0.05);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_creds_title { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_creds_caret { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_creds_status {
  color: #f2d866; background: rgba(255,255,255,0.08);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_creds_body { border-top-color: rgba(255,255,255,0.10); }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_cred_row { border-bottom-color: rgba(255,255,255,0.07); }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_cred_eye {
  background: rgba(255,255,255,0.10);
  border-color: rgba(255,255,255,0.20);
  color: #f2d866;
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_cred_eye:hover {
  background: rgba(255,255,255,0.18);
  border-color: #f2d866;
  color: #fff;
}

body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_inline_panel {
  background: rgba(255,255,255,0.04); border-color: rgba(255,255,255,0.10);
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_chip_row { color: #e2e8f0; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_settings_link_btn { color: #f2d866; }

body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_check_row ._eli3_cc_toggle_btn {
  /* keeps its blue gradient — primary action */
}

/* Footer buttons in dark mode — slate-on-slate, NOT platinum. The old
   near-white platinum gradient screamed against the dark navy command
   center bg. New scheme: subtle slate gradient with light gray text,
   gold accent on hover (matches the kernel premium accent). */
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_footer_row ._eli3_cc_toggle_btn {
  background: linear-gradient(to bottom, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.02) 100%) !important;
  border: 1px solid rgba(255,255,255,0.12) !important;
  color: #cbd5e1 !important;
  text-shadow: none !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04), 0 1px 2px rgba(0,0,0,0.2) !important;
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_footer_row ._eli3_cc_toggle_btn:hover {
  background: linear-gradient(to bottom, rgba(201,162,39,0.15) 0%, rgba(201,162,39,0.05) 100%) !important;
  border-color: rgba(201,162,39,0.5) !important;
  color: #f2d866 !important;
}
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_reset_btn { color: #fb7185 !important; }
body.beta-ui-active:not(.light-mode) ._eli3_cc_root ._eli3_cc_reset_btn:hover {
  background: linear-gradient(to bottom, rgba(251,113,133,0.15) 0%, rgba(251,113,133,0.05) 100%) !important;
  border-color: rgba(251,113,133,0.5) !important;
  color: #f87171 !important;
}
